# Independently authored native expectations outside the bounded selector increment.
# No compatibility credit; a neighboring observation is not necessarily a current runtime defect.
check<-function(name,expr){tryCatch(cat(if(isTRUE(force(expr)))"PASS" else "FAIL",name,"\n"),error=function(e)cat("ERROR",name,conditionMessage(e),"\n"))}
check("generic default dispatch method default value",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({events<-character();g<-function(x={events<<-c(events,"generic x");1L})UseMethod("g");g.integer<-function(x={events<<-c(events,"method x");2L})list(x=x,events=events,classes=.Class);g()}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list(error = "no applicable method for 'g' applied to an object of class \"NULL\""),
    warnings = character(0))))
check("generic local replacement dispatch",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({g<-function(x){x<-1L;UseMethod("g")};g.integer<-function(x)list("integer",x,.Class);g.character<-function(x)list("character",x,.Class);g("original")}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list("character", "original", "character"), warnings = character(0))))
check("missing generic input",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({g<-function(x)UseMethod("g");g.default<-function(x)list(missing=missing(x),classes=.Class,method=.Method);g()}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list(missing = TRUE, classes = NULL, method = "g.default"),
    warnings = character(0))))
check("explicit missing generic input",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({g<-function(x)UseMethod("g");g.name<-function(x)list(missing=missing(x),classes=.Class,method=.Method);g(x=)}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list(missing = TRUE, classes = "name", method = "g.name"),
    warnings = character(0))))
check("NextMethod explicit extra named argument observation",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({g<-function(x,y)UseMethod("g",1L);g.integer<-function(x,y)NextMethod(y=9L);g.numeric<-function(x,y)list(x=x,y=y,classes=.Class);g("original",2L)}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list(error = "unused argument (y)"), warnings = character(0))))
check("forwarded missing original with a method default",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({g<-function(x)UseMethod("g",1L);g.integer<-function(x=7L)list(missing=missing(x),value=x,classes=.Class);h<-function(x)g(x);h()}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list(error = "argument \"x\" is missing, with no default"),
    warnings = character(0))))
